using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;
namespace Xinghai.MapEditor.Editor {public static class MaterialContractM12Proof {
 public static void Run(){try{string path="Assets/M12MaterialContract/assembled.fbx";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);var mats=AssetDatabase.LoadAllAssetsAtPath(path).OfType<Material>().ToArray();var colors=(JArray)JObject.Parse(File.ReadAllText(Path.ChangeExtension(path,"xhmaterials.json")))["colors"];int textures=0;foreach(var c in colors){var m=mats.Single(x=>x.name==c.Value<string>("colorId"));var rgb=c["baseColor_sRGB"].ToObject<float[]>();if(Vector3.Distance(new Vector3(m.color.r,m.color.g,m.color.b),new Vector3(rgb[0],rgb[1],rgb[2]))>.0001f)throw new Exception("Color mismatch "+m.name);if(c.Value<bool>("baseColorTexture")){textures++;if(m.mainTexture==null)throw new Exception("Texture lost "+m.name);}if(c.Value<string>("alphaMode")=="MASK"&&Mathf.Abs(m.GetFloat("_Cutoff")-c.Value<float>("alphaCutoff"))>.0001f)throw new Exception("Alpha cutoff not retained");}if(textures==0)throw new Exception("No texture fixture");File.WriteAllText("../m12/material-contract.json",new JObject{{"passed",true},{"materials",colors.Count},{"textures",textures},{"alphaCutoff",.35}}.ToString());Debug.Log("M12_MATERIAL_CONTRACT_PASS");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}}
